      "settings": {
        "section_fullwidth": true,
        "custom_liquid": "<style>
  .tjs-seo-footer {
    margin: 34px 0 0;
    padding: 34px 18px 30px;
    font-family: inherit;
    background: #ffffff;
    border-top: 1px solid rgba(0, 0, 0, 0.08);
    border-bottom: 1px solid rgba(0, 0, 0, 0.08);
  }

  .tjs-seo-footer * {
    box-sizing: border-box;
  }

  .tjs-seo-footer__inner {
    max-width: 1180px;
    margin: 0 auto;
  }

  .tjs-seo-footer__top {
    display: grid;
    grid-template-columns: 1.25fr 1.75fr;
    gap: 42px;
    align-items: start;
  }

  .tjs-seo-footer__brand {
    max-width: 430px;
  }

  .tjs-seo-footer__kicker {
    margin-bottom: 10px;
    color: #777;
    font-size: 10px;
    line-height: 1;
    letter-spacing: 1.4px;
    text-transform: uppercase;
    font-weight: 800;
  }

  .tjs-seo-footer__title {
    margin: 0;
    color: #111;
    font-size: clamp(24px, 2.6vw, 34px);
    line-height: 1.08;
    letter-spacing: -0.7px;
    font-weight: 700;
  }

  .tjs-seo-footer__text {
    margin-top: 14px;
    color: #666;
    font-size: 13px;
    line-height: 1.72;
    font-weight: 400;
  }

  .tjs-seo-footer__trust {
    display: flex;
    flex-wrap: wrap;
    gap: 10px 14px;
    margin-top: 18px;
  }

  .tjs-seo-footer__trust span {
    color: #333;
    font-size: 12px;
    line-height: 1;
    font-weight: 600;
  }

  .tjs-seo-footer__links {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 34px;
  }

  .tjs-seo-footer__group-title {
    margin: 0 0 14px;
    color: #111;
    font-size: 11px;
    line-height: 1;
    letter-spacing: 1.1px;
    text-transform: uppercase;
    font-weight: 800;
  }

  .tjs-seo-footer__list {
    display: grid;
    gap: 9px;
  }

  .tjs-seo-footer__link {
    color: #666;
    text-decoration: none;
    font-size: 13px;
    line-height: 1.35;
    font-weight: 400;
    transition: color 0.18s ease, transform 0.18s ease;
  }

  .tjs-seo-footer__link:hover {
    color: #111;
    transform: translateX(2px);
  }

  .tjs-seo-footer__pills {
    margin-top: 30px;
    padding-top: 22px;
    border-top: 1px solid rgba(0, 0, 0, 0.08);
    display: flex;
    flex-wrap: wrap;
    gap: 10px 18px;
  }

  .tjs-seo-footer__pill {
    color: #444;
    text-decoration: none;
    font-size: 12px;
    line-height: 1;
    font-weight: 500;
  }

  .tjs-seo-footer__pill:hover {
    color: #111;
    text-decoration: underline;
    text-underline-offset: 3px;
  }

  .tjs-seo-footer__mobile-button {
    display: none;
  }

  @media screen and (max-width: 989px) {
    .tjs-seo-footer__top {
      grid-template-columns: 1fr;
      gap: 28px;
    }

    .tjs-seo-footer__brand {
      max-width: 100%;
    }

    .tjs-seo-footer__links {
      gap: 24px;
    }
  }

  @media screen and (max-width: 749px) {
    .tjs-seo-footer {
      margin-top: 28px;
      padding: 28px 16px 24px;
    }

    .tjs-seo-footer__top {
      gap: 24px;
    }

    .tjs-seo-footer__title {
      font-size: 25px;
      line-height: 1.12;
    }

    .tjs-seo-footer__text {
      font-size: 12.5px;
      line-height: 1.68;
    }

    .tjs-seo-footer__trust {
      gap: 9px 12px;
    }

    .tjs-seo-footer__trust span {
      font-size: 11.5px;
    }

    .tjs-seo-footer__links {
      grid-template-columns: 1fr;
      gap: 0;
      border-top: 1px solid rgba(0, 0, 0, 0.08);
    }

    .tjs-seo-footer__group {
      border-bottom: 1px solid rgba(0, 0, 0, 0.08);
    }

    .tjs-seo-footer__mobile-button {
      width: 100%;
      min-height: 48px;
      padding: 0;
      border: 0;
      background: transparent;
      color: #111;
      font-family: inherit;
      font-size: 11px;
      line-height: 1;
      letter-spacing: 1.1px;
      text-transform: uppercase;
      font-weight: 800;
      text-align: left;
      display: flex;
      align-items: center;
      justify-content: space-between;
      cursor: pointer;
    }

    .tjs-seo-footer__mobile-button::after {
      content: "+";
      color: #111;
      font-size: 18px;
      line-height: 1;
      font-weight: 400;
    }

    .tjs-seo-footer__group.is-open .tjs-seo-footer__mobile-button::after {
      content: "âˆ’";
    }

    .tjs-seo-footer__group-title {
      display: none;
    }

    .tjs-seo-footer__list {
      display: none;
      padding: 0 0 16px;
      gap: 10px;
    }

    .tjs-seo-footer__group.is-open .tjs-seo-footer__list {
      display: grid;
    }

    .tjs-seo-footer__link {
      font-size: 12.5px;
    }

    .tjs-seo-footer__pills {
      margin-top: 22px;
      padding-top: 18px;
      gap: 10px 14px;
    }

    .tjs-seo-footer__pill {
      font-size: 11.5px;
    }
  }
</style>

