#JuneChapters-{{ section.id }}{--jc-body-font:{{ face.family }},{{ face.fallback_families }};--jc-body-weight:{{ type.body_weight | default: 400 }};--jc-body-size:{{ type.body_size | default: 18 }}px;--jc-body-mobile:{{ type.body_mobile | default: 16 }}px;--jc-body-tracking:{{ type.body_tracking | default: -1 | divided_by: 100.0 }}em;--jc-body-leading:{{ type.body_leading | default: 150 | divided_by: 100.0 }};}
{% assign face = type.button_font | default: section.settings.fallback_font %}{% assign weight = type.button_weight | default: 600 | append: '' %}{% assign variant = face | font_modify: 'weight', weight | default: face %}{{ variant | font_face: font_display: 'swap' }}
#JuneChapters-{{ section.id }}{--jc-button-font:{{ face.family }},{{ face.fallback_families }};--jc-button-weight:{{ type.button_weight | default: 600 }};--jc-button-size:{{ type.button_size | default: 14 }}px;--jc-button-mobile:{{ type.button_mobile | default: 14 }}px;--jc-button-tracking:{{ type.button_tracking | default: -1 | divided_by: 100.0 }}em;--jc-button-leading:{{ type.button_leading | default: 130 | divided_by: 100.0 }};}
{% assign face = type.body_font | default: section.settings.fallback_font %}{% assign bold = face | font_modify: 'weight', '700' %}{{ bold | font_face: font_display: 'swap' }}
{% endstyle %}
{% capture arrow %}<span class="jc__arrow" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none"><path d="M5 12h14m-6-6 6 6-6 6" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"/></svg></span>{% endcapture %}
{% if chapters.size > 0 %}
<june-chapters class="jc" id="JuneChapters-{{ section.id }}" data-scroll="{{ section.settings.scroll }}" data-motion="{{ section.settings.motion }}" data-step="{{ section.settings.step }}" data-editor="{{ request.design_mode }}" data-pause-label="{{ section.settings.pause | escape }}" data-resume-label="{{ section.settings.resume | escape }}" aria-label="{{ section.settings.eyebrow | escape }}">
 <div class="jc__stage">
  <a class="jc__skip jc__button-type" href="#JuneChaptersEnd-{{ section.id }}">{{ section.settings.skip | escape }}</a>
  <div class="jc__scenes">
  {% for block in chapters %}
   {% liquid
    assign product = block.settings.product
    assign image_index = block.settings.image_number | minus: 1
    assign scene = block.settings.image | default: product.images[image_index] | default: product.featured_image
    assign mobile_scene = block.settings.mobile_image | default: scene
    assign write_index = block.settings.write_number | minus: 1
    assign wipe_index = block.settings.wipe_number | minus: 1
    assign write_image = product.images[write_index]
    assign wipe_image = product.images[wipe_index]
    assign alt = block.settings.alt | default: scene.alt | default: product.title
   %}
   <article class="jc__scene" data-scene="{{ forloop.index0 }}" data-effect="{{ block.settings.effect }}" data-block="{{ block.id }}" style="--jc-scene:{{ block.settings.background }};--jc-decoration:{{ block.settings.decoration }};--jc-local:0" aria-labelledby="JuneChapterTitle-{{ section.id }}-{{ forloop.index0 }}" {{ block.shopify_attributes }}>
    <div class="jc__copy">
     <p class="jc__eyebrow jc__button-type">{{ section.settings.eyebrow | escape }} <span aria-hidden="true"> / 0{{ forloop.index }}</span></p>
     <h2 class="jc__heading" id="JuneChapterTitle-{{ section.id }}-{{ forloop.index0 }}">{{ block.settings.heading | escape }}{% if block.settings.heading_second != blank %}<span>{{ block.settings.heading_second | escape }}</span>{% endif %}</h2>
     <div class="jc__body">{{ block.settings.body }}</div>
     {% if block.settings.show_shop and block.settings.collection != blank %}<a class="jc__primary jc__button-type" href="{{ block.settings.collection.url }}">{{ block.settings.shop | escape }}{{ arrow }}</a>{% endif %}
     {% if block.settings.note != blank %}<p class="jc__note jc__body">{{ block.settings.note | escape }}</p>{% endif %}
    </div>
    <div class="jc__visual">
     {% if scene != blank %}<picture class="jc__photo"><source media="(max-width:900px)" srcset="{{ mobile_scene | image_url: width: 600 }} 600w, {{ mobile_scene | image_url: width: 1000 }} 1000w" sizes="100vw">{{ scene | image_url: width: 1400 | image_tag: widths: '500,900,1400', sizes: '(min-width:1680px) 1000px, (min-width:901px) 58vw, 100vw', loading: 'lazy', alt: alt }}</picture>{% endif %}
     {% if block.settings.effect == 'petals' %}<div class="jc__petals" aria-hidden="true">{% for i in (1..12) %}<i style="--n:{{ i }};--angle:{{ i | times: 30 }}deg"></i>{% endfor %}</div>{% endif %}
     {% if block.settings.effect == 'wipe' and write_image != blank and wipe_image != blank %}
      <div class="jc__write" aria-hidden="true">{{ write_image | image_url: width: 1200 | image_tag: loading: 'lazy', alt: '' }}</div>
      <div class="jc__wipe" aria-hidden="true">{{ wipe_image | image_url: width: 1200 | image_tag: loading: 'lazy', alt: '' }}</div>
     {% endif %}
     {% if block.settings.effect == 'memories' %}<div class="jc__footprints" aria-hidden="true">{% for i in (1..2) %}<svg viewBox="0 0 70 120" style="--foot:{{ i }}"><ellipse cx="35" cy="75" rx="17" ry="32"/><ellipse cx="16" cy="28" rx="9" ry="13"/><ellipse cx="34" cy="18" rx="7" ry="10"/><ellipse cx="49" cy="20" rx="6" ry="9"/><ellipse cx="60" cy="30" rx="5" ry="7"/><ellipse cx="65" cy="43" rx="4" ry="6"/></svg>{% endfor %}</div>{% endif %}
    </div>
   </article>
  {% endfor %}
  </div>
  <div class="jc__navigation">
   <div class="jc__tabs" role="group" aria-label="{{ section.settings.navigation | escape }}">{% for block in chapters %}<button class="jc__tab jc__button-type" type="button" data-select="{{ forloop.index0 }}" aria-pressed="{% if forloop.first %}true{% else %}false{% endif %}" aria-controls="JuneChapterTitle-{{ section.id }}-{{ forloop.index0 }}"><span class="jc__dot" aria-hidden="true"></span>{{ block.settings.label | escape }}</button>{% endfor %}</div>
   <div class="jc__motion"><p class="jc__hint jc__button-type">{{ section.settings.hint | escape }}</p><button class="jc__pause jc__button-type" type="button" aria-pressed="false" data-pause>{{ section.settings.pause | escape }}</button></div>
  </div>
 </div>
</june-chapters>
<div id="JuneChaptersEnd-{{ section.id }}" tabindex="-1"></div>
{% endif %}
{% stylesheet %}
june-chapters.jc{display:block;max-width:1680px;margin:auto;color:var(--jc-ink);background:var(--jc-bg)}.jc *{box-sizing:border-box}.jc h2,.jc p{margin:0;color:inherit}.jc a{color:inherit;text-decoration:none}.jc button{color:inherit;cursor:pointer;appearance:none}.jc button:focus-visible,.jc a:focus-visible{outline:2px solid currentColor;outline-offset:5px}.jc strong{font-weight:700}
