.jc__visual{min-width:0;position:relative;overflow:hidden;isolation:isolate}.jc__photo,.jc__write,.jc__wipe{display:block;position:absolute;inset:0}.jc__visual img{display:block;width:100%;height:100%;object-fit:contain}.jc__visual:after{content:"";position:absolute;inset:0 auto 0 0;width:7%;background:linear-gradient(90deg,var(--jc-scene),transparent);pointer-events:none}.jc__write,.jc__wipe{opacity:0;background:var(--jc-scene);pointer-events:none}.jc__write{opacity:var(--write,0)}.jc__wipe{opacity:var(--wipe,0);clip-path:inset(0 calc((1 - var(--wipe,0))*100%) 0 0)}
