isplay:flex;align-items:flex-start;justify-content:center;gap:14px;max-width:1320px;margin:0 auto}.ju .ju__cover{mix-blend-mode:multiply;flex:1;min-width:0;text-align:center}.ju__cover-art{mix-blend-mode:multiply;display:block;height:calc(var(--ju-stage)*1.12);transform:scale(.94);transform-origin:50% 80%;transition:transform var(--ju-duration) ease}.ju__cover-art img{mix-blend-mode:multiply;transform:scale(1.1)}.ju__cover.is-selected .ju__cover-art{transform:scale(1)}.ju__caption{display:flex;flex-direction:column;align-items:center;gap:7px;padding:10px 8px 22px}.ju__number{font-size:var(--ju-label-size);font-weight:var(--ju-label-weight)}.ju__selected{font-size:var(--ju-button-size);font-weight:var(--ju-button-weight);visibility:hidden;min-height:30px;padding:6px 16px;border-radius:999px;background:var(--ju-accent);color:#111}.ju__name{padding-bottom:4px;border-bottom:2px solid transparent}.ju__cover.is-selected .ju__name{border-color:currentColor}.ju__cover.is-selected .ju__selected{visibility:visible}.ju .ju__step{position:absolute;top:42%;width:52px;height:52px;border:1px solid #1119;border-radius:50%;display:grid;place-items:center}.ju__step .ju__arrow{background:transparent;color:inherit}.ju__prev{left:24px}.ju__prev svg{transform:rotate(180deg)}.ju__next{right:24px}.ju__details{border-top:1px solid #1113;background:color-mix(in srgb,var(--ju-accent) 7%,var(--ju-bg))}.ju__panel{display:grid;grid-template-columns:minmax(0,1.15fr) minmax(0,1fr) minmax(0,1fr);align-items:center;gap:24px;padding:32px 48px;max-width:1420px;margin:0 auto}.ju__preview{height:300px;min-width:0}.ju__preview>div{height:100%}.ju__preview img{mix-blend-mode:multiply}.ju__inside-copy .ju__label{margin-bottom:12px}.ju__inside-copy .ju__body{margin-top:10px}.ju__toggles{display:flex;gap:22px;margin-top:20px}.ju__toggles button{min-height:44px;border-bottom:2px solid transparent;opacity:.55}.ju__toggles button[aria-pressed=true]{border-color:currentColor;opacity:1}.ju__buy{align-self:stretch