100%;margin:0}.ju__dialog{padding:20px}.ju__comparison{grid-template-columns:1fr;gap:20px}.ju__comparison article{display:grid;grid-template-columns:100px 1fr;column-gap:14px;border-bottom:1px solid #1113;padding-bottom:15px}.ju__comparison img{height:150px;grid-row:span 4}.ju__comparison h4{margin:0}.ju__comparison p{margin:3px 0}}
