          "id": "button_weight",
          "label": "Thickness",
          "min": 100,
          "max": 900,
          "step": 100,
          "default": 600
        },
        {
          "type": "range",
          "id": "button_tracking",
          "label": "Letter spacing (hundredths em)",
          "min": -6,
          "max": 20,
          "step": 1,
          "default": -1
        },
        {
          "type": "range",
          "id": "button_leading",
          "label": "Line spacing (%)",
          "min": 90,
          "max": 180,
          "step": 5,
          "default": 130
        }
      ]
    }
  ],
  "presets": [
    {
      "name": "June \u00b7 Your year",
      "blocks": [
        {
          "type": "planner"
        },
        {
          "type": "planner"
        },
        {
          "type": "planner"
        },
        {
          "type": "typography"
        }
      ]
